using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDayAPI.Data; using RaceDayAPI.Models;
namespace RaceDayAPI.Controllers;
[ApiController, Route("api/enrolments")]
public class EnrollmentsController : ControllerBase
{
    private readonly RaceDayDbContext _db; public EnrollmentsController(RaceDayDbContext db) => _db = db;
    [HttpGet, Authorize] public async Task<IActionResult> GetAll() { var id = int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); if (User.IsInRole("Organiser")) return Ok(await _db.Enrollments.AsNoTracking().ToListAsync()); return Ok(await _db.Enrollments.AsNoTracking().Where(x => x.ParticipantID == id).ToListAsync()); }
    [HttpGet("{id:int}"), Authorize] public async Task<IActionResult> Get(int id) { var x = await _db.Enrollments.AsNoTracking().FirstOrDefaultAsync(e => e.EnrollmentID == id); if (x == null) return NotFound(); if (!User.IsInRole("Organiser") && x.ParticipantID != int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!)) return Forbid(); return Ok(x); }
    [HttpGet("/api/events/{eventId:int}/enrolments"), Authorize(Roles = "Organiser")] public async Task<IActionResult> GetForEvent(int eventId) { if (!await _db.Events.AnyAsync(e => e.EventID == eventId)) return NotFound("Event not found."); return Ok(await _db.Enrollments.AsNoTracking().Where(e => e.EventID == eventId).ToListAsync()); }
    public record EnrollmentRequest(int EventID, int? RaceNumber);
    [HttpPost, Authorize(Roles = "Participant")] public async Task<IActionResult> Create(EnrollmentRequest r) { var uid = int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); if (!await _db.Events.AnyAsync(e => e.EventID == r.EventID)) return NotFound("Event not found."); if (await _db.Enrollments.AnyAsync(e => e.EventID == r.EventID && e.ParticipantID == uid)) return Conflict("You are already enrolled in this event."); int race = r.RaceNumber ?? ((await _db.Enrollments.MaxAsync(e => (int?)e.RaceNumber) ?? 1000) + 1); if (race <= 0 || await _db.Enrollments.AnyAsync(e => e.RaceNumber == race)) return Conflict("Race number must be positive and unique."); var x = new Enrollment { EventID = r.EventID, ParticipantID = uid, EnrollmentDate = DateTime.Today, RaceNumber = race }; _db.Enrollments.Add(x); await _db.SaveChangesAsync(); return CreatedAtAction(nameof(Get), new { id = x.EnrollmentID }, x); }
    [HttpDelete("{id:int}"), Authorize] public async Task<IActionResult> Delete(int id) { var x = await _db.Enrollments.FindAsync(id); if (x == null) return NotFound(); if (!User.IsInRole("Organiser") && x.ParticipantID != int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!)) return Forbid(); if (await _db.Results.AnyAsync(r => r.EnrollmentID == id)) return Conflict("This enrollment has a result. Remove the result first."); _db.Enrollments.Remove(x); await _db.SaveChangesAsync(); return NoContent(); }
}
